package com.example.starter.weight.domain;

/**
 * 称重方式：动态称重 / 静态复检。
 */
public enum WeighMode {
    /**
     * 动态称重（不停车检测）。
     */
    DYNAMIC,
    /**
     * 静态复检（停车复磅，与动态不一致时以此为准）。
     */
    STATIC
}

package com.example.starter.weight.domain;

/**
 * 过磅记录在证据链中的角色。
 */
public enum RecordRole {
    /**
     * 当前作为判定依据的有效记录。
     */
    AUTHORITATIVE,
    /**
     * 已被同“车牌+检测站+过磅时刻”的静态复检取代，仅保留可查。
     */
    SUPERSEDED,
    /**
     * 案件结案后才到达的迟到过磅数据，仅入证据备查，不改判已结案件。
     */
    LATE_EVIDENCE
}

package com.example.starter.weight.domain;

/**
 * 超限分档口径。
 */
public enum DecisionTier {
    /**
     * 实测总重未超过限值（超限率恰为 0 或为负）：不超限，直接放行。
     */
    NO_OVERLOAD,
    /**
     * 超限率大于 0 且不足 30%：责令卸载放行。
     */
    UNLOAD_RELEASE,
    /**
     * 超限率达到 30% 及以上（恰 30% 落入本档）：罚款并记分。
     */
    FINE_POINTS
}

package com.example.starter.weight.domain;

/**
 * 执法文书类型。
 */
public enum DocType {
    /**
     * 责令卸载放行文书（超限率不足 30%）。
     */
    UNLOAD_RELEASE,
    /**
     * 罚款记分处罚决定书（超限率达到 30% 及以上）。
     */
    PENALTY,
    /**
     * 复检推翻原处罚后生成的撤销文书。
     */
    REVOCATION,
    /**
     * 不超限放行告知（无违法）。
     */
    NO_ACTION
}

package com.example.starter.weight.domain;

/**
 * 处罚决定执行状态。
 */
public enum DecisionStatus {
    /**
     * 决定已送达并生效；复检期间亦不停止执行。
     */
    ACTIVE,
    /**
     * 经复检推翻，原决定已在同一事务内撤销。
     */
    REVOKED
}

package com.example.starter.weight.domain;

/**
 * 案件状态。
 */
public enum CaseStatus {
    /**
     * 案件处理中（含复检期间），处罚不停止执行。
     */
    OPEN,
    /**
     * 结案（终态）：迟到过磅数据仅入证据备查，不改判。
     */
    CLOSED
}

package com.example.starter.weight.domain;

/**
 * 复检申请与结论状态。
 */
public enum ReviewStatus {
    /**
     * 复检申请已受理、待结论；期间处罚不停止执行。
     */
    UNDER_REVIEW,
    /**
     * 复检维持原处罚。
     */
    UPHELD,
    /**
     * 复检推翻原处罚：原决定已撤销、记分与罚款已退还。
     */
    OVERTURNED
}

